"use client";

import { useEffect, useState } from "react";
import AppShell from "@/app/components/AppShell";
import VerificationBadge from "@/app/components/VerificationBadge";
import SovereignBadge from "@/app/components/SovereignBadge";
import Badge from "@/app/components/Badge";
import { getAuditLog } from "@/app/services/api";
import { downloadJson } from "@/app/services/fileDownload";
import type { AuditEntry } from "@/app/types";

export default function AuditLogPage() {
  const [entries, setEntries] = useState<AuditEntry[]>([]);
  const [total, setTotal] = useState(0);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [selectedEntry, setSelectedEntry] = useState<AuditEntry | null>(null);
  const [deptFilter, setDeptFilter] = useState("all");

  useEffect(() => {
    async function fetchAudit() {
      setLoading(true);
      try {
        const data = await getAuditLog(50, 0);
        setEntries(data.entries);
        setTotal(data.total);
      } catch (err) {
        setError(err instanceof Error ? err.message : "Audit records unavailable");
        setEntries([]);
        setTotal(0);
      } finally {
        setLoading(false);
      }
    }

    fetchAudit();
  }, []);

  const filtered = entries.filter((e) => deptFilter === "all" || e.department === deptFilter);

  const handleExport = () => {
    downloadJson("local-audit-records.json", {
      type: "LOCAL_AUDIT_LOG_EXPORT",
      total_records: filtered.length,
      exported_at: new Date().toISOString(),
      compliance: "Application audit records; not independently immutable storage",
      records: filtered,
    });
  };

  return (
    <AppShell
      title="Local Audit Trail"
      subtitle="Application and security events"
      breadcrumbs={[
        { label: "Workspace", href: "/workspace" },
        { label: "Audit Trail" },
      ]}
    >
      <div className="space-y-6 max-w-7xl mx-auto pb-12">
        {/* Header Notice */}
        <div className="p-6 bg-surface border border-border rounded-2xl shadow-xs space-y-2">
          <div className="flex flex-wrap items-center justify-between gap-3">
            <div>
              <h2 className="font-serif text-xl font-bold text-text">
                Statutory Regulatory & Operational Audit Trail
              </h2>
              <p className="text-xs text-text-3 font-mono">
                Application audit records. Off-host immutable retention must be configured separately.
              </p>
            </div>
            <div className="flex items-center gap-2">
              <SovereignBadge size="sm" />
              <button
                onClick={handleExport}
                className="px-4 py-2 rounded-xl bg-accent text-white hover:bg-accent-hover text-xs font-semibold shadow-xs transition-colors cursor-pointer"
              >
                Export Audit (.JSON / CSV)
              </button>
            </div>
          </div>
        </div>

        {error && (
          <div className="p-4 bg-amber-500/10 border border-amber-500/20 rounded-2xl flex items-center gap-3 text-xs font-mono text-amber-700">
            <span className="text-base">🛡️</span>
            <span>{error}</span>
          </div>
        )}

        {/* Filter Bar */}
        <div className="flex items-center justify-between p-4 bg-surface border border-border rounded-2xl shadow-xs text-xs font-mono">
          <div className="flex items-center gap-2">
            <span className="text-text-3 uppercase">Filter Department:</span>
            <select
              value={deptFilter}
              onChange={(e) => setDeptFilter(e.target.value)}
              className="bg-surface-2 border border-border px-2.5 py-1.5 rounded-xl text-text font-semibold focus:outline-none"
            >
              <option value="all">All Departments</option>
              <option value="OPERATIONS">OPERATIONS</option>
              <option value="MAINTENANCE">MAINTENANCE</option>
              <option value="SAFETY">SAFETY (HSE)</option>
              <option value="ENGINEERING">ENGINEERING</option>
              <option value="AUDIT">AUDIT</option>
            </select>
          </div>

          <span className="text-text-3">
            Showing {filtered.length} of {total} records
          </span>
        </div>

        {/* Table */}
        <div className="bg-surface border border-border rounded-2xl overflow-hidden shadow-xs p-5 space-y-3">
          {loading ? (
            <div className="p-8 text-center text-xs text-text-3">Loading WORM ledger...</div>
          ) : (
            <div className="overflow-x-auto">
              <table className="w-full text-left text-xs font-sans border-collapse">
                <thead>
                  <tr className="border-b border-border text-text-3 font-mono text-[11px] uppercase">
                    <th className="pb-2.5">Task / Audit ID</th>
                    <th className="pb-2.5">User</th>
                    <th className="pb-2.5">Department</th>
                    <th className="pb-2.5">Query Description</th>
                    <th className="pb-2.5">Agents Invoked</th>
                    <th className="pb-2.5">Confidence</th>
                    <th className="pb-2.5">Verification</th>
                    <th className="pb-2.5 text-right">Details</th>
                  </tr>
                </thead>
                <tbody className="divide-y divide-border/60">
                  {filtered.map((entry, idx) => (
                    <tr
                      key={idx}
                      onClick={() => setSelectedEntry(entry)}
                      className="hover:bg-bg-base/70 transition-colors cursor-pointer"
                    >
                      <td className="py-3 font-mono font-bold text-accent">
                        {entry.investigation_id}
                      </td>
                      <td className="py-3 font-semibold text-text">{entry.user}</td>
                      <td className="py-3 font-mono text-[11px] text-text-2">
                        <span className="px-2 py-0.5 rounded bg-surface-2 border border-border">
                          {entry.department}
                        </span>
                      </td>
                      <td className="py-3 font-medium text-text max-w-xs truncate">
                        {entry.query}
                      </td>
                      <td className="py-3">
                        <div className="flex flex-wrap gap-1">
                          {entry.agents_invoked.map((a) => (
                            <span
                              key={a}
                              className="px-1.5 py-0.2 rounded bg-surface-2 border border-border text-[10px] font-mono text-text-3"
                            >
                              {a.replace("_agent", "")}
                            </span>
                          ))}
                        </div>
                      </td>
                      <td className="py-3 font-mono font-semibold text-text">
                        {Math.round(entry.confidence * 100)}%
                      </td>
                      <td className="py-3">
                        <VerificationBadge status={entry.verification_status} size="sm" />
                      </td>
                      <td className="py-3 text-right">
                        <span className="text-text-3 hover:text-accent font-mono text-[11px]">
                          Inspect →
                        </span>
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          )}
        </div>

        {/* Read-Only WORM Detail Drawer */}
        {selectedEntry && (
          <div className="fixed inset-0 bg-black/40 backdrop-blur-xs flex items-center justify-end z-50 p-4">
            <div className="bg-surface border border-border rounded-2xl p-6 max-w-lg w-full h-[90vh] shadow-xl flex flex-col justify-between space-y-4 overflow-y-auto">
              <div className="space-y-4">
                <div className="flex items-center justify-between border-b border-border pb-3">
                  <div>
                    <h3 className="font-serif font-bold text-base text-text">
                      WORM Audit Record Details
                    </h3>
                    <span className="font-mono text-xs text-accent">
                      {selectedEntry.investigation_id}
                    </span>
                  </div>
                  <button
                    onClick={() => setSelectedEntry(null)}
                    className="p-1 rounded-lg text-text-3 hover:text-text"
                  >
                    ✕
                  </button>
                </div>

                <div className="space-y-3 text-xs font-mono">
                  <div className="p-3 bg-surface-2/50 rounded-xl space-y-1">
                    <span className="text-[10px] text-text-3 uppercase">Operator</span>
                    <p className="font-bold text-text text-sm">
                      {selectedEntry.user} ({selectedEntry.department})
                    </p>
                  </div>

                  <div className="p-3 bg-surface-2/50 rounded-xl space-y-1">
                    <span className="text-[10px] text-text-3 uppercase">Timestamp</span>
                    <p className="text-text">{selectedEntry.timestamp}</p>
                  </div>

                  <div className="p-3 bg-surface-2/50 rounded-xl space-y-1">
                    <span className="text-[10px] text-text-3 uppercase">Query</span>
                    <p className="text-text font-sans font-medium text-xs">{selectedEntry.query}</p>
                  </div>

                  <div className="p-3 bg-surface-2/50 rounded-xl space-y-1">
                    <span className="text-[10px] text-text-3 uppercase">Agents & Tools Invoked</span>
                    <div className="flex flex-wrap gap-1 pt-1">
                      {selectedEntry.agents_invoked.map((a) => (
                        <span key={a} className="px-2 py-0.5 rounded bg-surface border border-border text-text">
                          {a}
                        </span>
                      ))}
                    </div>
                  </div>

                  <div className="p-3 bg-surface-2/50 rounded-xl space-y-1">
                    <span className="text-[10px] text-text-3 uppercase">Verification & Confidence</span>
                    <div className="flex items-center gap-3 pt-1">
                      <VerificationBadge status={selectedEntry.verification_status} />
                      <span className="font-bold text-text">
                        {(selectedEntry.confidence * 100).toFixed(0)}% Statistical Confidence
                      </span>
                    </div>
                  </div>
                </div>
              </div>

              <div className="pt-4 border-t border-border flex items-center justify-between text-xs text-text-3 font-mono">
                <span>Read-Only Compliance Record</span>
                <button
                  onClick={() => setSelectedEntry(null)}
                  className="px-4 py-2 rounded-xl bg-surface-2 hover:bg-surface border border-border text-text font-medium cursor-pointer"
                >
                  Close
                </button>
              </div>
            </div>
          </div>
        )}
      </div>
    </AppShell>
  );
}

"use client";

import React, { useState } from "react";
import ModelChip from "./ModelChip";

interface BoundingBox {
  label: string;
  box_2d: number[]; // [ymin, xmin, ymax, xmax] in 0-1000 or 0-1 normalized
  confidence?: number;
}

interface AnnotatedImageProps {
  imageUrl: string;
  alt: string;
  boxes?: BoundingBox[];
  caption?: string;
  modelUsed?: string;
  className?: string;
}

export default function AnnotatedImage({
  imageUrl,
  alt,
  boxes = [
    { label: "P-204A Outboard Bearing (Hot Spot: 78.4°C)", box_2d: [300, 320, 650, 680], confidence: 0.98 },
    { label: "Bypass Valve HV-204B (Standby Closed)", box_2d: [150, 700, 350, 880], confidence: 0.94 },
  ],
  caption = "VLM Object & Anomaly Detection on CDU-II P&ID / Thermal Inspection",
  modelUsed = "Qwen2.5-VL · vision",
  className = "",
}: AnnotatedImageProps) {
  const [showBoxes, setShowBoxes] = useState(true);

  return (
    <div className={`space-y-3 p-4 bg-surface border border-border rounded-2xl shadow-xs ${className}`}>
      <div className="flex items-center justify-between">
        <div className="flex items-center gap-2">
          <span className="text-base">👁️</span>
          <span className="font-serif font-bold text-sm text-text">Multimodal VLM Inspection</span>
        </div>
        <div className="flex items-center gap-2">
          {modelUsed && <ModelChip model={modelUsed} size="sm" />}
          <button
            onClick={() => setShowBoxes(!showBoxes)}
            className="text-xs px-2.5 py-1 rounded-lg border border-border bg-surface-2 hover:bg-surface text-text font-medium"
          >
            {showBoxes ? "Hide Overlays" : "Show Bounding Boxes"}
          </button>
        </div>
      </div>

      {/* Image with SVG bounding-box overlay */}
      <div className="relative aspect-[16/10] bg-surface-2/60 rounded-xl overflow-hidden border border-border flex items-center justify-center">
        {/* Placeholder SVG diagram if image URL is mock */}
        <div className="absolute inset-0 flex flex-col items-center justify-center p-6 text-center text-text-3">
          <svg className="w-full h-full max-h-56 opacity-25" viewBox="0 0 400 240" fill="none" stroke="currentColor">
            <rect x="80" y="80" width="140" height="90" rx="8" strokeWidth="2" />
            <circle cx="150" cy="125" r="30" strokeWidth="2" />
            <path d="M220 125h80M300 80v90M300 125l50 30" strokeWidth="2" />
          </svg>
        </div>

        {/* Bounding box overlays */}
        {showBoxes && (
          <div className="absolute inset-0 pointer-events-none p-4">
            {boxes.map((box, i) => {
              // Convert 0-1000 scale to %
              const [ymin, xmin, ymax, xmax] = box.box_2d.map((v) => (v > 1 ? v / 10 : v * 100));
              const top = `${ymin}%`;
              const left = `${xmin}%`;
              const width = `${xmax - xmin}%`;
              const height = `${ymax - ymin}%`;

              return (
                <div
                  key={i}
                  style={{ top, left, width, height }}
                  className="absolute border-2 border-accent bg-accent/15 rounded-md pointer-events-auto transition-all hover:bg-accent/25"
                >
                  <span className="absolute -top-6 left-0 px-2 py-0.5 rounded bg-accent text-white text-[10px] font-mono font-semibold whitespace-nowrap shadow-xs">
                    {box.label} {box.confidence ? `(${(box.confidence * 100).toFixed(0)}%)` : ""}
                  </span>
                </div>
              );
            })}
          </div>
        )}
      </div>

      {caption && (
        <p className="text-xs text-text-2 leading-relaxed text-center font-mono">
          {caption}
        </p>
      )}
    </div>
  );
}

"use client";

import React from "react";
import Link from "next/link";
import type { ArtifactItem } from "@/app/types";

import ModelChip from "./ModelChip";

interface ArtifactCardProps {
  artifact: ArtifactItem;
  taskId: string;
  className?: string;
}

function formatSize(bytes: number) {
  if (bytes < 1024) return `${bytes} B`;
  if (bytes < 1024 * 1024) return `${(bytes / 1024).toFixed(1)} KB`;
  return `${(bytes / (1024 * 1024)).toFixed(1)} MB`;
}

export default function ArtifactCard({
  artifact,
  taskId,
  className = "",
}: ArtifactCardProps) {
  let typeLabel = "Document";
  let icon = "📄";
  let color = "bg-blue-500";

  switch (artifact.type) {
    case "docx":
      typeLabel = "Word Deliverable";
      icon = "📘";
      color = "bg-[#2b579a]";
      break;
    case "pptx":
      typeLabel = "PowerPoint Slides";
      icon = "📙";
      color = "bg-[#d24726]";
      break;
    case "xlsx":
      typeLabel = "Excel Spreadsheet";
      icon = "📗";
      color = "bg-[#217346]";
      break;
    case "code":
      typeLabel = "Python Script";
      icon = "💻";
      color = "bg-[#3572A5]";
      break;
    case "image":
      typeLabel = "Annotated Diagram";
      icon = "🖼️";
      color = "bg-[#9146FF]";
      break;
  }

  const handleDownload = (e: React.MouseEvent) => {
    e.stopPropagation();
    window.location.assign(artifact.download_url);
  };

  return (
    <div
      className={`p-4 rounded-2xl bg-surface border border-border hover:border-accent/40 shadow-xs hover:shadow-sm transition-all space-y-3 ${className}`}
    >
      <div className="flex items-start justify-between gap-2">
        <div className="flex items-center gap-2.5">
          <span className="text-2xl">{icon}</span>
          <div>
            <h4 className="font-semibold text-xs text-text truncate max-w-[190px]" title={artifact.name}>
              {artifact.name}
            </h4>
            <div className="flex items-center gap-1.5 text-[10px] text-text-3 font-mono">
              <span>{typeLabel}</span>
              <span>·</span>
              <span>{formatSize(artifact.size_bytes)}</span>
            </div>
          </div>
        </div>
      </div>

      {artifact.metadata?.summary && (
        <p className="text-xs text-text-2 line-clamp-2 leading-relaxed">
          {artifact.metadata.summary}
        </p>
      )}

      <div className="flex items-center justify-between pt-1 border-t border-border-subtle">
        <ModelChip model={artifact.model_used} size="sm" />

        <div className="flex items-center gap-1.5">
          <Link
            href={`/task/${taskId}/artifact/${artifact.id}`}
            className="px-2.5 py-1 rounded-lg bg-surface-2 hover:bg-surface text-text text-[11px] font-medium border border-border transition-colors"
          >
            Open Viewer
          </Link>
          <button
            onClick={handleDownload}
            className="px-2.5 py-1 rounded-lg bg-accent text-white hover:bg-accent-hover text-[11px] font-semibold transition-colors shadow-2xs"
          >
            Download
          </button>
        </div>
      </div>
    </div>
  );
}

"use client";

import { useState, useEffect, useRef, useCallback, FormEvent, DragEvent } from "react";
import { useSession } from "@/app/hooks/useSession";
import {
  createConversation,
  getConversation,
  sendChatMessage,
  uploadChatFile,
  uploadChatFilesBatch,
  deleteConversation,
} from "@/app/services/api";
import type { ChatMessage, ChatAttachment } from "@/app/types";

interface ChatWindowProps {
  conversationId: string | null;
  type?: "general" | "report";
  investigationId?: string;
  onConversationCreated?: (id: string) => void;
  onConversationDeleted?: (id: string) => void;
  compact?: boolean;
}

import MarkdownMessage from "@/app/components/MarkdownMessage";


// ─── Suggested Chips for Empty State ──────────────────────────────────
const GENERAL_SUGGESTIONS = [
  "What are common causes of bearing failure in industrial pumps?",
  "Explain vibration analysis techniques for rotating equipment",
  "What PPE is required for confined space entry?",
  "Summarize ISO 13849 safety standards",
  "How do I perform a root cause analysis for equipment failure?",
  "What is the ISO 10816 vibration severity standard?",
];

const REPORT_SUGGESTIONS = [
  "What were the key findings?",
  "What evidence supports the conclusion?",
  "Are there any unverified findings?",
  "What maintenance actions are recommended?",
];

const ALLOWED_EXTENSIONS = new Set([
  ".pdf",
  ".txt",
  ".csv",
  ".docx",
  ".text",
  ".md",
  ".json",
  ".png",
  ".jpg",
  ".jpeg",
  ".webp",
  ".gif",
  ".svg",
]);

export default function ChatWindow({
  conversationId,
  type = "general",
  investigationId,
  onConversationCreated,
  onConversationDeleted,
  compact = false,
}: ChatWindowProps) {
  const { session } = useSession();
  const [messages, setMessages] = useState<ChatMessage[]>([]);
  const [input, setInput] = useState("");
  const [sending, setSending] = useState(false);
  const [loading, setLoading] = useState(false);
  const [isDeleting, setIsDeleting] = useState(false);
  const [currentConvId, setCurrentConvId] = useState<string | null>(conversationId);
  const [attachments, setAttachments] = useState<ChatAttachment[]>([]);
  const [uploadingCount, setUploadingCount] = useState<number>(0);
  const [uploadError, setUploadError] = useState<string | null>(null);
  const [dragOver, setDragOver] = useState(false);
  const messagesEndRef = useRef<HTMLDivElement>(null);
  const textareaRef = useRef<HTMLTextAreaElement>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);
  const folderInputRef = useRef<HTMLInputElement>(null);

  const handleDeleteCurrentChat = useCallback(async () => {
    if (!currentConvId) return;
    if (!window.confirm("Are you sure you want to delete this chat?")) return;
    setIsDeleting(true);
    try {
      const convIdToDelete = currentConvId;
      await deleteConversation(convIdToDelete);
      setMessages([]);
      setCurrentConvId(null);
      if (onConversationDeleted) {
        onConversationDeleted(convIdToDelete);
      }
      const reloadSidebar = (window as unknown as Record<string, unknown>).__reloadSidebar;
      if (typeof reloadSidebar === "function") {
        (reloadSidebar as () => void)();
      }
    } catch (err) {
      console.error("Failed to delete chat:", err);
      alert("Failed to delete chat. Please try again.");
    } finally {
      setIsDeleting(false);
    }
  }, [currentConvId, onConversationDeleted]);

  // Sync conversationId prop — also clear attachments/errors for a fresh state
  useEffect(() => {
    const timer = setTimeout(() => { setCurrentConvId(conversationId); setAttachments([]); setUploadError(null); }, 0);
    return () => clearTimeout(timer);
  }, [conversationId]);

  // Load conversation messages when conversationId changes
  useEffect(() => {
    if (!currentConvId) {
      const timer = setTimeout(() => setMessages([]), 0);
      return () => clearTimeout(timer);
    }

    let cancelled = false;
    async function load() {
      try {
        const detail = await getConversation(currentConvId!);
        if (!cancelled) {
          setMessages(detail.messages);
        }
      } catch {
        // Fail silently
      } finally {
        if (!cancelled) setLoading(false);
      }
    }
    load();
    return () => { cancelled = true; };
  }, [currentConvId]);

  // Auto-scroll to bottom
  useEffect(() => {
    messagesEndRef.current?.scrollIntoView({ behavior: "smooth" });
  }, [messages, sending]);

  // Auto-resize textarea
  const handleTextareaChange = useCallback((value: string) => {
    setInput(value);
    if (textareaRef.current) {
      textareaRef.current.style.height = "auto";
      textareaRef.current.style.height = Math.min(textareaRef.current.scrollHeight, 120) + "px";
    }
  }, []);

  // ─── File Upload (Multiple files & Folders) ────────────────────────
  const handleFileUpload = useCallback(async (files: FileList | File[]) => {
    setUploadError(null);
    const rawFiles = Array.from(files);
    if (rawFiles.length === 0) return;

    // Filter out hidden/system files and validate extensions
    const validFiles = rawFiles.filter((file) => {
      if (file.name.startsWith(".") || file.name === "Thumbs.db" || file.name === "desktop.ini") {
        return false;
      }
      const dotIndex = file.name.lastIndexOf(".");
      if (dotIndex === -1) return false;
      const ext = file.name.substring(dotIndex).toLowerCase();
      return ALLOWED_EXTENSIONS.has(ext);
    });

    if (validFiles.length === 0) {
      setUploadError(
        "No supported files found. Supported formats: PDF, TXT, CSV, DOCX, MD, JSON, PNG, JPG, WEBP, GIF, SVG."
      );
      return;
    }

    const paths = validFiles.map(
      (file) => ((file as unknown as { webkitRelativePath?: string }).webkitRelativePath || file.name)
    );

    setUploadingCount(validFiles.length);

    try {
      // 1. Primary: Use batch upload
      const uploaded = await uploadChatFilesBatch(validFiles, paths);
      const newAttachments: ChatAttachment[] = uploaded.map((item) => ({
        filename: item.filename,
        url: item.url,
        type: (item.type === "image" ? "image" : "document") as "document" | "image",
        extracted_text: item.extracted_text,
        relative_path: item.relative_path,
        source_id: item.source_id,
        size: item.size,
      }));

      if (newAttachments.length > 0) {
        setAttachments((prev) => [...prev, ...newAttachments]);
      }
    } catch (err) {
      console.warn("Batch upload failed, falling back to individual upload:", err);
      // 2. Fallback: upload file-by-file
      try {
        const results = await Promise.allSettled(
          validFiles.map(async (file) => {
            const formData = new FormData();
            formData.append("file", file);
            return await uploadChatFile(formData);
          })
        );

        const newAttachments: ChatAttachment[] = [];
        let failCount = 0;

        results.forEach((res, i) => {
          if (res.status === "fulfilled") {
            const result = res.value;
            newAttachments.push({
              filename: result.filename,
              url: result.url,
              type: result.type as "document" | "image",
              extracted_text: result.extracted_text_preview || undefined,
              relative_path: paths[i],
            });
          } else {
            failCount++;
          }
        });

        if (newAttachments.length > 0) {
          setAttachments((prev) => [...prev, ...newAttachments]);
        }

        if (failCount > 0) {
          setUploadError(
            failCount === validFiles.length
              ? "Failed to upload selected file(s). Please try again."
              : `${failCount} of ${validFiles.length} file(s) could not be uploaded.`
          );
        }
      } catch (fallbackErr) {
        setUploadError(
          fallbackErr instanceof Error ? fallbackErr.message : "Failed to upload files"
        );
      }
    } finally {
      setUploadingCount(0);
    }
  }, []);

  const handleDrop = useCallback(
    (e: DragEvent) => {
      e.preventDefault();
      setDragOver(false);
      if (e.dataTransfer.files.length > 0) {
        handleFileUpload(e.dataTransfer.files);
      }
    },
    [handleFileUpload]
  );

  const removeAttachment = useCallback((index: number) => {
    setAttachments((prev) => prev.filter((_, i) => i !== index));
  }, []);

  const clearAllAttachments = useCallback(() => {
    setAttachments([]);
  }, []);

  // ─── Send Message ─────────────────────────────────────────────────
  const handleSend = useCallback(
    async (messageText?: string) => {
      const content = (messageText || input).trim();
      if (!content || sending || !session) return;

      setSending(true);
      setInput("");
      if (textareaRef.current) {
        textareaRef.current.style.height = "auto";
      }

      try {
        let convId = currentConvId;

        // Create conversation if needed
        if (!convId) {
          const conv = await createConversation({
            session_id: session.session_id,
            title: content.length > 60 ? content.substring(0, 60) + "…" : content,
            type,
            investigation_id: investigationId,
          });
          convId = conv.id;
          setCurrentConvId(convId);
          onConversationCreated?.(convId);

          // Reload sidebar
          const reloadSidebar = (window as unknown as Record<string, unknown>).__reloadSidebar;
          if (typeof reloadSidebar === "function") {
            (reloadSidebar as () => void)();
          }
        }

        // Optimistically add user message
        const userMsg: ChatMessage = {
          id: `temp-${Date.now()}`,
          role: "user",
          content,
          attachments: [...attachments],
          created_at: new Date().toISOString(),
        };
        setMessages((prev) => [...prev, userMsg]);
        const currentAttachments = [...attachments];
        setAttachments([]);

        // Send to API
        const response = await sendChatMessage(convId, content, currentAttachments);

        // Add assistant response
        setMessages((prev) => [
          ...prev,
          {
            id: response.id,
            role: "assistant" as const,
            content: response.content,
            attachments: response.attachments || [],
            created_at: response.created_at,
          },
        ]);
      } catch (err) {
        console.error("Chat send error:", err);
        const errMsg =
          err instanceof Error
            ? err.message
            : "Sorry, I encountered an error. Please try again.";
        // Show error in chat
        setMessages((prev) => [
          ...prev,
          {
            id: `error-${Date.now()}`,
            role: "assistant" as const,
            content: errMsg.includes("error")
              ? errMsg
              : `Sorry, I encountered an error: ${errMsg}`,
            attachments: [],
            created_at: new Date().toISOString(),
          },
        ]);
      } finally {
        setSending(false);
      }
    },
    [input, sending, session, currentConvId, type, investigationId, attachments, onConversationCreated]
  );

  const handleSubmit = useCallback(
    (e: FormEvent) => {
      e.preventDefault();
      handleSend();
    },
    [handleSend]
  );

  const suggestions = type === "report" ? REPORT_SUGGESTIONS : GENERAL_SUGGESTIONS;

  return (
    <div
      style={{
        display: "flex",
        flexDirection: "column",
        height: compact ? "100%" : "100%",
        position: "relative",
      }}
      onDragOver={(e) => {
        e.preventDefault();
        setDragOver(true);
      }}
      onDragLeave={() => setDragOver(false)}
      onDrop={handleDrop}
    >
      {/* Drop zone overlay */}
      {dragOver && (
        <div className="drop-zone-overlay">
          <span>Drop files or folders to attach</span>
        </div>
      )}

      {/* ─── Active Chat Header ─────────────────────────────────────── */}
      {currentConvId && (
        <div className="chat-window-header">
          <div className="chat-window-header-info">
            <span className="chat-window-header-status-dot" />
            <span className="chat-window-header-title">
              {type === "report" ? "Report Discussion" : "Active Chat"}
            </span>
          </div>
          <button
            type="button"
            className="chat-window-delete-btn"
            title="Delete this chat"
            aria-label="Delete this chat"
            onClick={handleDeleteCurrentChat}
            disabled={isDeleting}
          >
            {isDeleting ? (
              <span
                className="animate-spin"
                style={{
                  display: "inline-block",
                  width: "12px",
                  height: "12px",
                  border: "2px solid currentColor",
                  borderTopColor: "transparent",
                  borderRadius: "50%",
                }}
              />
            ) : (
              <svg
                width="13"
                height="13"
                viewBox="0 0 24 24"
                fill="none"
                stroke="currentColor"
                strokeWidth="2"
                strokeLinecap="round"
                strokeLinejoin="round"
              >
                <polyline points="3 6 5 6 21 6" />
                <path d="M19 6v14a2 2 0 0 1-2 2H7a2 2 0 0 1-2-2V6m3 0V4a2 2 0 0 1 2-2h4a2 2 0 0 1 2 2v2" />
                <line x1="10" y1="11" x2="10" y2="17" />
                <line x1="14" y1="11" x2="14" y2="17" />
              </svg>
            )}
            <span>{isDeleting ? "Deleting..." : "Delete Chat"}</span>
          </button>
        </div>
      )}

      {/* ─── Messages Area ───────────────────────────────────────────── */}
      {loading ? (
        <div className="chat-messages">
          {[1, 2, 3].map((i) => (
            <div
              key={i}
              className="animate-pulse"
              style={{
                alignSelf: i % 2 === 0 ? "flex-end" : "flex-start",
                width: `${40 + i * 10}%`,
                height: "48px",
                background: "var(--color-surface-2)",
                borderRadius: "16px",
              }}
            />
          ))}
        </div>
      ) : messages.length === 0 && !sending ? (
        <div className="chat-empty">
          <div className="chat-empty-icon" style={{ fontSize: "2.5rem" }}>
            {type === "report" ? "📋" : "  "}
          </div>
          <div>
            <h3
              className="font-[family-name:var(--font-playfair)]"
              style={{
                fontSize: "1.375rem",
                fontWeight: 400,
                color: "var(--color-text)",
                marginBottom: "8px",
                letterSpacing: "-0.02em",
              }}
            >
              {type === "report"
                ? "Ask about this report"
                : "What can I help you investigate?"}
            </h3>
            <p style={{ fontSize: "0.8125rem", color: "var(--color-text-3)", marginBottom: "4px" }}>
              {type === "report"
                ? "Ask follow-up questions grounded in the investigation findings."
                : "Ask about industrial safety, equipment health, or engineering standards. You can also attach files below."}
            </p>
          </div>
          <div style={{ display: "flex", flexWrap: "wrap", gap: "8px", justifyContent: "center", maxWidth: "560px" }}>
            {suggestions.map((q, i) => (
              <button
                key={i}
                onClick={() => handleSend(q)}
                className="animate-fade-in-up-small"
                style={{
                  animationDelay: `${(i + 1) * 60}ms`,
                  background: "var(--color-surface-2)",
                  border: "1px solid var(--color-border)",
                  borderRadius: "10px",
                  padding: "8px 14px",
                  fontSize: "0.75rem",
                  color: "var(--color-text-2)",
                  cursor: "pointer",
                  transition: "all 0.2s ease",
                  maxWidth: "260px",
                  textAlign: "left",
                  lineHeight: 1.4,
                }}
                onMouseEnter={(e) => {
                  e.currentTarget.style.borderColor = "var(--color-accent)";
                  e.currentTarget.style.color = "var(--color-accent)";
                  e.currentTarget.style.transform = "translateY(-1px)";
                  e.currentTarget.style.boxShadow = "0 4px 12px rgba(0,0,0,0.08)";
                }}
                onMouseLeave={(e) => {
                  e.currentTarget.style.borderColor = "var(--color-border)";
                  e.currentTarget.style.color = "var(--color-text-2)";
                  e.currentTarget.style.transform = "translateY(0)";
                  e.currentTarget.style.boxShadow = "none";
                }}
              >
                {q}
              </button>
            ))}
          </div>
        </div>
      ) : (
        <div className="chat-messages">
          {messages.map((msg) => (
            <div key={msg.id}>
              <div
                className={`chat-bubble ${
                  msg.role === "user" ? "chat-bubble-user" : "chat-bubble-assistant"
                }`}
              >
                {/* Render attachments */}
                {msg.attachments && msg.attachments.length > 0 && (
                  <div style={{ display: "flex", flexWrap: "wrap", gap: "6px", marginBottom: "8px" }}>
                    {msg.attachments.map((att, i) =>
                      att.type === "image" ? (
                        <img
                          key={i}
                          src={att.url}
                          alt={att.filename}
                          style={{
                            maxWidth: "200px",
                            maxHeight: "150px",
                            borderRadius: "8px",
                            border: "1px solid var(--color-border)",
                          }}
                        />
                      ) : (
                        <span key={i} className="attachment-chip">
                          <svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2">
                            <path d="M14 2H6a2 2 0 0 0-2 2v16a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V8z" />
                            <polyline points="14 2 14 8 20 8" />
                          </svg>
                          <span className="attachment-chip-name">{att.filename}</span>
                        </span>
                      )
                    )}
                  </div>
                )}

                {/* Render message content */}
                <MarkdownMessage content={msg.content} />
              </div>
              <div
                className="chat-timestamp"
                style={{ textAlign: msg.role === "user" ? "right" : "left" }}
              >
                {new Date(msg.created_at).toLocaleTimeString("en-US", {
                  hour: "numeric",
                  minute: "2-digit",
                })}
              </div>
            </div>
          ))}

          {/* Typing indicator */}
          {sending && (
            <div className="chat-bubble chat-bubble-assistant">
              <div className="typing-indicator">
                <div className="typing-dot" />
                <div className="typing-dot" />
                <div className="typing-dot" />
              </div>
            </div>
          )}

          <div ref={messagesEndRef} />
        </div>
      )}

      {/* ─── Composer ────────────────────────────────────────────────── */}
      <div className="chat-composer">
        {/* Upload error banner */}
        {uploadError && (
          <div
            style={{
              padding: "6px 12px",
              marginBottom: "8px",
              background: "rgba(186, 56, 56, 0.1)",
              border: "1px solid rgba(186, 56, 56, 0.25)",
              borderRadius: "8px",
              fontSize: "0.75rem",
              color: "var(--color-red)",
              display: "flex",
              alignItems: "center",
              justifyContent: "space-between",
            }}
          >
            <span>{uploadError}</span>
            <button
              onClick={() => setUploadError(null)}
              style={{
                background: "none",
                border: "none",
                color: "var(--color-red)",
                cursor: "pointer",
                fontWeight: "bold",
              }}
            >
              ×
            </button>
          </div>
        )}

        {/* Attachment previews */}
        {attachments.length > 0 && (
          <div
            style={{
              display: "flex",
              flexWrap: "wrap",
              gap: "6px",
              marginBottom: "8px",
              maxHeight: "120px",
              overflowY: "auto",
              paddingRight: "4px",
            }}
          >
            {attachments.map((att, i) => (
              <span
                key={i}
                className="attachment-chip"
                title={att.relative_path || att.filename}
                style={{ display: "inline-flex", alignItems: "center", gap: "6px" }}
              >
                <span>{att.type === "image" ? "🖼" : att.relative_path?.includes("/") ? "📁" : "📄"}</span>
                <span className="attachment-chip-name" style={{ maxWidth: "200px", overflow: "hidden", textOverflow: "ellipsis", whiteSpace: "nowrap" }}>
                  {att.relative_path && att.relative_path !== att.filename ? att.relative_path : att.filename}
                </span>
                <button
                  type="button"
                  onClick={() => removeAttachment(i)}
                  title="Remove attachment"
                  style={{
                    background: "none",
                    border: "none",
                    cursor: "pointer",
                    padding: "0 2px",
                    color: "inherit",
                    opacity: 0.7,
                  }}
                >
                  ×
                </button>
              </span>
            ))}
            {attachments.length > 2 && (
              <button
                type="button"
                onClick={clearAllAttachments}
                style={{
                  background: "none",
                  border: "none",
                  color: "var(--color-text-3)",
                  fontSize: "0.6875rem",
                  cursor: "pointer",
                  padding: "2px 6px",
                  textDecoration: "underline",
                }}
              >
                Clear all ({attachments.length})
              </button>
            )}
            {uploadingCount > 0 && (
              <span className="attachment-chip" style={{ opacity: 0.8 }}>
                <svg className="animate-spin" width="12" height="12" viewBox="0 0 24 24" fill="none">
                  <circle cx="12" cy="12" r="10" stroke="currentColor" strokeWidth="3" opacity="0.3" />
                  <path d="M12 2a10 10 0 0 1 10 10" stroke="currentColor" strokeWidth="3" strokeLinecap="round" />
                </svg>
                {uploadingCount === 1 ? "Uploading 1 file…" : `Uploading ${uploadingCount} files…`}
              </span>
            )}
          </div>
        )}

        <form onSubmit={handleSubmit}>
          <div className="chat-composer-inner">
            {/* Attach multiple files button */}
            <button
              type="button"
              onClick={() => fileInputRef.current?.click()}
              title="Attach files (select multiple files)"
              style={{
                background: "none",
                border: "none",
                cursor: "pointer",
                padding: "4px",
                color: "var(--color-text-3)",
                transition: "color 0.15s ease",
                flexShrink: 0,
              }}
              onMouseEnter={(e) => (e.currentTarget.style.color = "var(--color-accent)")}
              onMouseLeave={(e) => (e.currentTarget.style.color = "var(--color-text-3)")}
            >
              <svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
                <path d="M21.44 11.05l-9.19 9.19a6 6 0 0 1-8.49-8.49l9.19-9.19a4 4 0 0 1 5.66 5.66l-9.2 9.19a2 2 0 0 1-2.83-2.83l8.49-8.48" />
              </svg>
            </button>
            <input
              ref={fileInputRef}
              type="file"
              multiple
              accept=".pdf,.txt,.csv,.docx,.png,.jpg,.jpeg,.webp,.gif,.md,.json"
              style={{ display: "none" }}
              onChange={(e) => {
                if (e.target.files && e.target.files.length > 0) {
                  handleFileUpload(e.target.files);
                }
                e.target.value = "";
              }}
            />

            {/* Attach folder button */}
            <button
              type="button"
              onClick={() => folderInputRef.current?.click()}
              title="Attach folder (select directory)"
              style={{
                background: "none",
                border: "none",
                cursor: "pointer",
                padding: "4px",
                color: "var(--color-text-3)",
                transition: "color 0.15s ease",
                flexShrink: 0,
              }}
              onMouseEnter={(e) => (e.currentTarget.style.color = "var(--color-accent)")}
              onMouseLeave={(e) => (e.currentTarget.style.color = "var(--color-text-3)")}
            >
              <svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
                <path d="M22 19a2 2 0 0 1-2 2H4a2 2 0 0 1-2-2V5a2 2 0 0 1 2-2h5l2 3h9a2 2 0 0 1 2 2z" />
              </svg>
            </button>
            <input
              ref={folderInputRef}
              type="file"
              {...{ webkitdirectory: "", directory: "", multiple: true }}
              style={{ display: "none" }}
              onChange={(e) => {
                if (e.target.files && e.target.files.length > 0) {
                  handleFileUpload(e.target.files);
                }
                e.target.value = "";
              }}
            />

            {/* Text input */}
            <textarea
              ref={textareaRef}
              value={input}
              onChange={(e) => handleTextareaChange(e.target.value)}
              placeholder={
                type === "report"
                  ? "Ask about this report…"
                  : "Ask KavachAI anything…"
              }
              rows={1}
              onKeyDown={(e) => {
                if (e.key === "Enter" && !e.shiftKey) {
                  e.preventDefault();
                  handleSend();
                }
              }}
            />

            {/* Send button */}
            <button
              type="submit"
              disabled={(!input.trim() && attachments.length === 0) || sending}
              style={{
                background: "var(--color-accent)",
                color: "#faf8f5",
                border: "none",
                borderRadius: "10px",
                padding: "6px 10px",
                cursor: "pointer",
                transition: "all 0.15s ease",
                flexShrink: 0,
                opacity: (!input.trim() && attachments.length === 0) || sending ? 0.4 : 1,
              }}
              title="Send message"
            >
              <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
                <line x1="22" y1="2" x2="11" y2="13" />
                <polygon points="22 2 15 22 11 13 2 9 22 2" />
              </svg>
            </button>
          </div>
        </form>
      </div>
    </div>
  );
}

"use client";

import React from "react";
import Link from "next/link";
import Badge from "./Badge";

export interface KBDocumentRow {
  id: string;
  filename: string;
  type: string;
  department: string;
  pageCount: number;
  chunkCount: number;
  ocrTier: string;
  status: "indexed" | "ocr_processing" | "embedding" | "queued" | "failed";
  ingestedAt: string;
}

interface DocumentTableProps {
  documents: KBDocumentRow[];
  onSelectDoc?: (doc: KBDocumentRow) => void;
  className?: string;
}

export default function DocumentTable({
  documents,
  onSelectDoc,
  className = "",
}: DocumentTableProps) {
  return (
    <div className={`bg-surface border border-border rounded-2xl overflow-hidden shadow-xs space-y-3 p-5 ${className}`}>
      <div className="flex items-center justify-between pb-2 border-b border-border-subtle">
        <div>
          <h3 className="font-serif font-bold text-base text-text">Ingested Document Repository</h3>
          <p className="text-xs text-text-3 font-mono">
            Full-text extracted and chunked locally with multi-tier OCR pipeline
          </p>
        </div>
      </div>

      <div className="overflow-x-auto">
        <table className="w-full text-left text-xs font-sans border-collapse">
          <thead>
            <tr className="border-b border-border text-text-3 font-mono text-[11px] uppercase">
              <th className="pb-2.5">Document Name</th>
              <th className="pb-2.5">Scope</th>
              <th className="pb-2.5">Pages</th>
              <th className="pb-2.5">Chunks</th>
              <th className="pb-2.5">OCR Extraction Tier</th>
              <th className="pb-2.5">Status</th>
              <th className="pb-2.5 text-right">Detail</th>
            </tr>
          </thead>
          <tbody className="divide-y divide-border/60">
            {documents.map((doc) => (
              <tr key={doc.id} className="hover:bg-bg-base/70 transition-colors">
                <td className="py-3 font-medium text-text">
                  <div className="flex items-center gap-2">
                    <span className="text-base">
                      {doc.type === "pid" ? "📐" : doc.type === "image" ? "🖼️" : "📄"}
                    </span>
                    <span className="font-mono font-semibold text-xs truncate max-w-[220px]">
                      {doc.filename}
                    </span>
                  </div>
                </td>
                <td className="py-3 font-mono text-[11px] text-text-2">
                  <span className="px-2 py-0.5 rounded bg-surface-2 border border-border">
                    {doc.department}
                  </span>
                </td>
                <td className="py-3 font-mono text-text-2">{doc.pageCount}</td>
                <td className="py-3 font-mono text-text-2">{doc.chunkCount}</td>
                <td className="py-3 font-mono text-[11px] text-text-2">
                  <span className="px-2 py-0.5 rounded bg-surface-2 border border-border">
                    {doc.ocrTier}
                  </span>
                </td>
                <td className="py-3">
                  <Badge
                    variant={doc.status === "indexed" ? "complete" : doc.status === "ocr_processing" ? "running" : "queued"}
                    label={doc.status.toUpperCase()}
                    size="sm"
                  />
                </td>
                <td className="py-3 text-right">
                  <Link
                    href={`/knowledge-base/document/${doc.id}`}
                    className="px-2.5 py-1 rounded-lg bg-surface-2 hover:bg-surface border border-border text-[11px] text-text font-medium transition-colors"
                  >
                    Inspect
                  </Link>
                </td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>
    </div>
  );
}

"use client";

import React from "react";
import Link from "next/link";
import { usePathname, useRouter } from "next/navigation";
import { useSession } from "@/app/hooks/useSession";
import NetworkStatusPill from "./NetworkStatusPill";
import SovereignBadge from "./SovereignBadge";

interface HeaderProps {
  title?: string;
  subtitle?: string;
  showNewTaskButton?: boolean;
  breadcrumbs?: { label: string; href?: string }[];
  showBackToWorkspace?: boolean;
  showAuditLink?: boolean;
}

export default function Header({
  title,
  subtitle,
  showNewTaskButton = true,
  breadcrumbs,
  showBackToWorkspace,
  showAuditLink,
}: HeaderProps) {
  const pathname = usePathname();
  const router = useRouter();
  const { session, logout } = useSession();

  return (
    <header className="sticky top-0 z-20 bg-bg-base/90 backdrop-blur-md border-b border-border-subtle h-14 flex items-center justify-between px-6">
      {/* ─── Left: Breadcrumbs or Page Title ───────────────────────── */}
      <div className="flex items-center gap-3 min-w-0">
        {breadcrumbs && breadcrumbs.length > 0 ? (
          <nav className="flex items-center gap-1.5 text-xs text-text-3 font-medium">
            {breadcrumbs.map((crumb, idx) => (
              <React.Fragment key={idx}>
                {idx > 0 && <span className="opacity-40">/</span>}
                {crumb.href ? (
                  <Link
                    href={crumb.href}
                    className="hover:text-accent transition-colors truncate max-w-[140px]"
                  >
                    {crumb.label}
                  </Link>
                ) : (
                  <span className="text-text font-semibold truncate max-w-[200px]">
                    {crumb.label}
                  </span>
                )}
              </React.Fragment>
            ))}
          </nav>
        ) : (
          <div className="flex items-baseline gap-2 truncate">
            {title && (
              <h1 className="font-serif font-bold text-base text-text tracking-tight truncate">
                {title}
              </h1>
            )}
            {subtitle && (
              <span className="text-xs text-text-3 font-mono hidden sm:inline truncate">
                · {subtitle}
              </span>
            )}
          </div>
        )}
      </div>

      {/* ─── Right: Sovereignty Badge, Network Pill, Actions ───────── */}
      <div className="flex items-center gap-3 shrink-0">
        <SovereignBadge size="sm" className="hidden md:inline-flex" />

        <NetworkStatusPill compact={true} />

        {showNewTaskButton && pathname !== "/workspace" && pathname !== "/task/new" && (
          <Link
            href="/workspace"
            className="flex items-center gap-1.5 px-3 py-1.5 rounded-lg bg-accent text-white text-xs font-semibold hover:bg-accent-hover transition-colors shadow-xs"
          >
            <span>+</span>
            <span>New Task</span>
          </Link>
        )}

        {/* User Mini Avatar / Info */}
        {session && (
          <div className="flex items-center gap-2 pl-2 border-l border-border text-xs">
            <span className="w-6 h-6 rounded-full bg-accent/15 text-accent font-bold flex items-center justify-center text-[10px]">
              {session.name.slice(0, 2).toUpperCase()}
            </span>
            <span className="text-text-2 font-medium hidden lg:inline">
              {session.name}
            </span>
          </div>
        )}
      </div>
    </header>
  );
}

"use client";

import React from "react";

interface ModelChipProps {
  model: string;
  taskType?: string;
  size?: "sm" | "md";
  className?: string;
}

export default function ModelChip({
  model,
  taskType,
  size = "md",
  className = "",
}: ModelChipProps) {
  // Extract icon based on taskType or model name
  const lower = (model + " " + (taskType || "")).toLowerCase();
  let icon = "⚡";
  let role = "reasoning";

  if (lower.includes("vision") || lower.includes("vl") || lower.includes("image") || lower.includes("pid")) {
    icon = "👁️";
    role = "vision";
  } else if (lower.includes("code") || lower.includes("coder") || lower.includes("sandbox") || lower.includes("python")) {
    icon = "💻";
    role = "code";
  } else if (lower.includes("embed") || lower.includes("nomic")) {
    icon = "🔍";
    role = "embedding";
  } else if (lower.includes("ocr") || lower.includes("document") || lower.includes("tesseract")) {
    icon = "📄";
    role = "OCR";
  }

  const isSm = size === "sm";

  return (
    <span
      className={`inline-flex items-center gap-1.5 font-mono rounded-md border border-border bg-surface-2 text-text font-medium ${
        isSm ? "px-2 py-0.5 text-[11px]" : "px-2.5 py-1 text-xs"
      } ${className}`}
      title={`Served locally via on-premise Ollama/vLLM runtime (${model})`}
    >
      <span className="text-xs">{icon}</span>
      <span className="font-semibold text-text">{model}</span>
      {taskType && (
        <>
          <span className="text-text-3 font-normal">·</span>
          <span className="text-text-2 font-sans capitalize">{taskType.replace(/_/g, " ")}</span>
        </>
      )}
    </span>
  );
}

"use client";

import { useState } from "react";
import type { TopologyNode, BypassLoop } from "@/app/types";

interface PidRelationshipProps {
  components: string[];
  highlighted?: string;
  visionObservation?: string | null;
  boundingBox?: number[] | null;
  processTopology?: TopologyNode[] | null;
  bypassLoops?: BypassLoop[] | null;
}

const DEFAULT_NODE_INFO: Record<string, { name: string; role: string; spec: string; status: string }> = {};

export default function PidRelationship({
  components,
