  const topologyMap = new Map<string, { name: string; role: string; spec: string; status: string }>();
  if (processTopology) {
    processTopology.forEach((node) => {
      topologyMap.set(node.tag, {
        name: node.name,
        role: node.role,
        spec: node.spec,
        status: node.status,
      });
    });
  }

  const getNodeInfo = (tag: string) => {
