// ─── Investigations ─────────────────────────────────────────────────

export async function uploadInvestigationFiles(
  files: File[],
  paths?: string[]
): Promise<AttachmentItem[]> {
  const formData = new FormData();
  files.forEach((f) => formData.append("files", f));
  if (paths && paths.length > 0) {
    formData.append("paths", JSON.stringify(paths));
  }
