export function getDownloadUrl(path: string): string {
  // If path starts with /, it's relative to the API base host
  if (path.startsWith("/")) {
    if (API_BASE.startsWith("http")) {
      try {
        const url = new URL(API_BASE);
        return `${url.origin}${path}`;
      } catch {
        return path;
      }
    }
    return path;
  }
  return path;
}

